INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62148577', 62148577, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI BESAR PELATIHAN KESEHATAN MAKASSAR', 'Keperluan Sehari-hari Perkantoran', 'Barang', 'Pengadaan Langsung', 'Sulawesi Selatan, Makassar (Kota)', 93636000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '68 OT', 'Penyediaan keperluan sehari-hari perkantoran untuk mendukung kelancaran operasional kantor, dengan ruang lingkup pekerjaan sebagai berikut: 1. Penyediaan Barang - Menyediakan berbagai keperluan kantor sesuai daftar kebutuhan yang ditentukan oleh instansi. - Barang yang disediakan harus baru, layak pakai, dan berkualitas. 2. Pengemasan dan Pengiriman - Mengemas barang dengan rapi agar tidak rusak saat pengiriman. - Mengirimkan barang ke lokasi kantor sesuai jadwal. 3. Pemeriksaan dan Serah Terima - Melakukan pengecekan jumlah dan kualitas barang sebelum diserahkan. - Menyerahkan barang dalam kondisi siap digunakan. 4. Pelaporan - Menyediakan laporan rinci jumlah dan jenis barang yang diterima.', '1. Alat Tulis Kantor (ATK) - Kertas (HVS, F4, A4) - Pulpen, pensil, spidol - Buku catatan/notebook - Map, binder, clip, staples - Penghapus, penggaris, dan alat tulis lainnya - Dan barang kebutuhan lainnya 2. Perlengkapan Pendukung - Tisu, tissue roll, hand sanitizer - Pembersih lantai dan meja - Kantong sampah - Alat kebersihan ringan (sapu, lap, ember) - Dan barang kebutuhan lainnya 3. Peralatan Kantor Kecil - Kalkulator - Stapler dan isi ulang staples - Pembolong kertas, gunting, cutter - Tape dan dispenser tape - Dan barang kebutuhan lainnya 4. Standar Mutu - Barang baru dan sesuai spesifikasi - Aman digunakan, tidak berbahaya - Berkualitas dan awet untuk penggunaan sehari-hari 5. Jumlah dan Distribusi - Disesuaikan dengan jumlah pegawai dan kebutuhan harian kantor 6. Waktu Pelaksanaan Pengadaan dan pengiriman dilakukan secara berkala sesuai kebutuhan atau kontrak (misal bulanan/triwulan) Ketentuan Tambahan - Harga sudah termasuk pengiriman ke lokasi kantor - Barang cacat atau tidak sesuai spesifikasi wajib diganti oleh penyedia - Penyedia wajib menjaga kualitas dan ketepatan waktu pengiriman', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 150662);
