INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62851406', 62851406, 'analyze_legacy', 'Kementerian Sekretariat Negara', 'central', 'SEKRETARIAT KEMENTERIAN SEKRETARIAT NEGARA', 'Layanan Internet Hambalang', 'Jasa Lainnya', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 4465337000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 0, 0, '1 paket', 'Layanan Internet Dedicated 10 Gbps akan disediakan di lingkungan Kompleks Hambalang untuk mendukung kebutuhan komunikasi data, sistem informasi pemerintahan, dan koordinasi kegiatan operasional yang melibatkan berbagai unit kerja di bawah Kementerian Sekretariat Negara. Layanan ini akan menggantikan koneksi internet eksisting yang memiliki keterbatasan kapasitas dan stabilitas, sekaligus menambahkan titik-titik baru pada lokasi yang strategis agar seluruh area operasional mendapatkan akses jaringan yang optimal. Layanan internet ini akan dilengkapi dengan fitur bandwidth management dan network monitoring system untuk memastikan kestabilan koneksi, mendeteksi gangguan secara dini apabila terjadi penurunan performa atau gangguan jaringan. Tujuan utama dari sistem ini adalah untuk memastikan konektivitas berkecepatan tinggi dan keamanan data tetap terjaga, khususnya dalam mendukung aktivitas komunikasi dan sistem aplikasi pemerintahan yang bersifat sensitif.', 'Minimum bandwidth dedicated dengan rasio upstream dan downstream 1:1- Mendapatkan IP Publik- Akses ke IIX Pusat terdekat tidak lebih dari 3 HOP- Koneksi akhir menggunakan Ethernet (RJ45)- Semua akses port terbuka- Mendapatkan ketersediaan dan informasi redundancy backbone- Menerima report utilisasi bandwidth yang dapat dilihat secara langsung oleh user atas penggunaannya- Mendapatkan perawatan, dukungan dan pelayanan 24x7 baik online maupun onsite- Menerima laporan bulanan mengenai performance dan penggunaan (traffic) bandwidth internet, laporan terdiri dari penggunaan traffic bits per detik- Mendapatkan contact service, sistem trouble ticketing dan eskalasi prosedur penanganan masalah yang jelas- Menerima dokumen meliputi detail instalasi, gambar jaringan, dan IP management- SLA 99,9%', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 156423);
